{
  "description": "Protect confirmed system-spec chapters and the canonical spec state from unsafe mutation, and record audit sub-agent forks as tamper-independent evidence.",
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Write|Edit|MultiEdit|Bash",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"${PLUGIN_ROOT:-${CLAUDE_PLUGIN_ROOT}}/hooks/guard-confirmed-chapter-overwrite.py\"",
            "timeout": 10
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Task|Agent",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"${PLUGIN_ROOT:-${CLAUDE_PLUGIN_ROOT}}/hooks/record-audit-fork.py\"",
            "timeout": 10
          }
        ]
      }
    ],
    "SubagentStop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"${PLUGIN_ROOT:-${CLAUDE_PLUGIN_ROOT}}/hooks/record-audit-fork.py\" --event subagent-stop",
            "timeout": 10
          }
        ]
      }
    ]
  }
}
{
  "rubric_id": "system-spec-completeness",
  "version": "0.1.0",
  "description": "生成された仕様書を上位概念・意思決定・網羅性・deep knowledge・鮮度・prompt品質で採点するfail-closed機械判定ルール。",
  "aspects": {
    "foundation_trace": {
      "label": "上位概念トレーサビリティ",
      "auditor": "assign-system-spec-completeness-evaluator",
      "component": "C05",
      "primary_input": "spec-state.json / 00-requirements-definition.md",
      "deterministic_gate": "validate-coverage-matrix.py --require-foundation",
      "pass_criteria": ["U1-U9が値または明示N/A理由で確定", "goal-objective-intent-cell-chapter traceにdanglingなし"]
    },
    "decision_guidance": {
      "label": "意思決定支援",
      "auditor": "assign-system-spec-completeness-evaluator",
      "component": "C05",
      "primary_input": "spec-state.json decisions[] / 00-requirements-definition.md",
      "deterministic_gate": "validate-coverage-matrix.py --require-foundation",
      "pass_criteria": ["needs_guidanceは2〜3案と無料/低コスト案を持つ", "最新公式証拠・goal fit・TCO・security・operations・lock-in・推奨理由・注意点がある", "AI推奨のみでconfirmedにしない"]
    },
    "matrix_coverage": {
      "label": "マトリクス網羅性",
      "auditor": "system-spec-matrix-auditor",
      "component": "C07",
      "sub_input_auditor": "system-spec-hearing-auditor (C06)",
      "primary_input": "spec-state.json",
      "deterministic_gate": "validate-coverage-matrix.py (--require-complete)",
      "pass_criteria": [
        "全カテゴリ×6 canonical platform セルが 未収集/対象外/確定 のいずれかで埋まり未収集 0",
        "対象外セルに具体的 reason、確定セルに qa_log/approval_log へ遡れる qa_ref がある",
        "category_aggregate が真理値表 (未着手/収集中/確定/対象外) と一致し宣言欠落が無い",
        "goal-spec 例示カテゴリを最低含むか excluded_categories の根拠がある",
        "sub-input: C06 (hearing-auditor) の監査 (軸は R6-audit-hearing の監査 5 軸 = 聞き漏れ/誘導質問/早期停止/トレーサビリティ/foundation 利用者根拠 が正本) を aspect-criteria.md 1a の対応表で判定して FAIL/INDETERMINATE が無く、確定セルが誘導なく漏れなく Q&A と利用者一次入力に遡れる (C06 の verdict はそのまま使わず aggregate-completeness.py --hearing で導く。注記と閉じた検出は findings に残す)",
        "C16 必須情報被覆 (機械層): validate-knowledge-graph.py --profile required-info が exit0 (全 in-scope domain 被覆・item 最低形状・収集順序・coverage certificate)。missing_effect=block の item が未回答のまま確定 (confirmed) に進んだ確定セルは C01 R5 収集ゲート素通り (C14 は blocking_items を列挙するのみで runtime 施行はせず、決定論 writer 施行 = apply-spec-transition への block 検査組込は follow-up) として FAIL に寄せる"
      ]
    },
    "design_knowledge_reflection": {
      "label": "設計知識反映",
      "auditor": "assign-system-spec-completeness-evaluator",
      "component": "C05",
      "self_evaluated": "C05 R1-score が自前評価する (独立 auditor なし)。C06 は仕様書 Markdown を読まないため design_knowledge に束縛しない (虚偽対応の撤去)",
      "primary_input": "system-spec/ 配下の全 Markdown (Path.rglob('*.md')) / ref-system-design-knowledge/references/resource-map.yaml",
      "deterministic_gate": null,
      "pass_criteria": [
        "機械層: コンパイル済み各章が resource-map.yaml 由来の設計知識ポインタ節を持つ (compile の render_design_refs が注入)",
        "意味層: そのポインタが指す原則 (DDD/クリーンアーキテクチャ/セキュアバイデザイン/API デザイン/クリーンコード等) が当該カテゴリの確定セル要件へ具体的に適用されている",
        "Goodhart 防止: ポインタの存在確認だけでは PASS にしない (compile が機械注入する存在を自己循環で肯定しない)。汎用ポインタ (resource-map 索引) のみで具体原則の適用が無い章は medium 以上で拾う",
        "C13 知識グラフ (機械層): validate-knowledge-graph.py --profile knowledge が exit0 (knowledge-catalog が typed 辺グラフで循環/dangling/孤立/root到達不能 0、depends_on/refines/conflicts_with 型則充足)。この機械層が保証するのは well-formedness (形状・辺型則・写像全射) と位相順の決定性のみで、知識辺の意味妥当性 (依存関係が設計上妥当か) は content-review/human の未閉塞責務",
        "C14 位相順消費 (機械層+意味層): --profile knowledge --order が返す topo_order を C01 R5-decision-guide と C03 R2 が同一順 (上位概念→下位概念) で消費している。位相順を破って下位技術を先に確定した章は FAIL に寄せる",
        "C15 doctrine anchor (機械層): validate-knowledge-graph.py --profile doctrine が exit0 (7 concern の concern_id 一意 + 各 authority 非空・全 category→concern 写像全射。authority は 4 種で concern 間共有可であり authority 一意性は検査対象外)。意味層: doctrine-anchor-registry の concern authority (Apple HIG/Clean Architecture/OWASP ASVS/Google SRE) が指す上流指針が生成章の確定セル要件へ具体反映されている (存在確認だけで PASS にしない = Goodhart 防止)"
      ]
    },
    "doc_freshness": {
      "label": "最新ドキュメント出典",
      "auditor": "system-spec-doc-freshness-auditor",
      "component": "C08",
      "primary_input": "fetched-references.json",
      "deterministic_gate": "validate-source-citation.py (C08 が実行)",
      "pass_criteria": [
        "対象 target を漏れなく参照し、必須フィールドと source_url host 一致を満たす",
        "official_host が publisher の公式ドキュメントホストであり非公式ミラーでない",
        "記録 version/last_updated が公式現行版から世代落ちしていない",
        "latest_checked_at/source_url が実効性を持って記録されている"
      ]
    },
    "prompt_quality": {
      "label": "prompt-creator準拠",
      "auditor": "assign-system-spec-completeness-evaluator",
      "component": "C05",
      "primary_input": "plugins/system-spec-harness/**/prompts/*.md",
      "deterministic_gate": "verify-completeness.py + validate-prompt.py",
      "deterministic_gate_dependency": "外部 plugin prompt-creator が verify-completeness.py / validate-prompt.py を提供する。依存 prompt-creator が解決できない単独 install 環境ではこの機械ゲートのみを skip し、INDETERMINATE を FAIL に倒さない (意味層 pass_criteria と独立 design findings は引き続き必須評価)。repo/CI 環境では両 validator を必須実行する",
      "pass_criteria": ["C1-C4/L7→L1/l5-contract v2.0を満たす", "客観的停止条件と実質深度を持つ", "独立design findingsにhighなし"]
    }
  },
  "aggregation": {
    "policy": "fail-closed",
    "overall_pass_requires": "全観点PASSかつhigh severity findingが0件",
    "high_max": 0,
    "notes": [
      "1 観点でも FAIL/INDETERMINATE なら総合 FAIL",
      "例外: prompt_quality の外部 prompt-creator 機械ゲート (verify-completeness.py/validate-prompt.py) が依存 plugin 不在で解決不能な単独 install 環境では、当該機械ゲートのみ skip し INDETERMINATE を FAIL に倒さない (deterministic_gate_dependency 参照)。意味層 pass_criteria が FAIL なら従来どおり総合 FAIL",
      "全観点を過不足なく網羅していなければ総合FAIL (監査観点の取りこぼし防止)",
      "総合判定は aggregate-completeness.aggregate_verdict で再導出でき、レポートの verdict と一致すること (Goodhart 防止)",
      "独立 auditor を名乗る観点 (primary=C07/C08、sub_input=C06) は audit_delegations[] の fork receipt を持ち、PostToolUse hook (hooks/record-audit-fork.py) の書く fork 台帳で session・tool・response digest・auditor verdict まで裏取りできること。裏取りできない帰属または緑化は fail-closed で violation = 総合 FAIL"
    ]
  },
  "attribution": {
    "policy": "fail-closed",
    "why": "aspects[].auditor は評価者自身が書く文字列であり、独立監査を 1 件も fork しない実行でも『独立 auditor が PASS を出した』と名乗れた。監査 agent は Write を持たず自力で痕跡を残せないため、証跡はモデルが書けない層 (PostToolUse hook) が書く append-only 台帳に置く",
    "ledger": "eval-log/system-spec-harness/audit-fork-ledger.jsonl (env SYSTEM_SPEC_AUDIT_FORK_LEDGER で上書き可)",
    "ledger_writer": "plugins/system-spec-harness/hooks/record-audit-fork.py (PostToolUse: Task|Agent = dispatch 行 / SubagentStop = completion 行 schema 1.3)",
    "required_receipts": [
      {"aspect": "matrix_coverage", "role": "primary", "auditor": "system-spec-matrix-auditor", "component": "C07"},
      {"aspect": "matrix_coverage", "role": "sub_input", "auditor": "system-spec-hearing-auditor", "component": "C06"},
      {"aspect": "doc_freshness", "role": "primary", "auditor": "system-spec-doc-freshness-auditor", "component": "C08"}
    ],
    "rules": [
      "C05 自前評価の観点 (foundation_trace/decision_guidance/design_knowledge_reflection/prompt_quality) に primary receipt を付けるのは虚偽の独立性主張として violation",
      "receipt の auditor は agents/<auditor>.md に実在すること (架空の agent 名を名乗らせない)",
      "role=primary の receipt.verdict は aspects[aspect].verdict と一致し、dispatch.{session_id,tool,subagent_type,tool_use_id,response_sha256} と receipt.verdict は hook 台帳の同一 response 記録と一致し、verdict_state=resolved の行だけを受理すること (監査判定の忠実転記。非同期 fork は SubagentStop の completion 行で昇格した digest を使う)",
      "台帳が存在しない/空の実行は裏取り 0 件として fail-closed (緑にしない)"
    ],
    "machine_layer_limits": "台帳は hook が観測した auditor verdict の書換えを拒否する。監査 prompt の意味的十分性・根拠妥当性、および改ざん可能な台帳環境への対策は content-review/human と運用上の書込み権限分離の責務"
  },
  "aspect_to_auditor": {
    "foundation_trace": "assign-system-spec-completeness-evaluator",
    "decision_guidance": "assign-system-spec-completeness-evaluator",
    "matrix_coverage": "system-spec-matrix-auditor",
    "design_knowledge_reflection": "assign-system-spec-completeness-evaluator",
    "doc_freshness": "system-spec-doc-freshness-auditor",
    "prompt_quality": "assign-system-spec-completeness-evaluator"
  },
  "matrix_coverage_sub_input": "system-spec-hearing-auditor",
  "design_knowledge_self_evaluated": true
}

