"""Extract doctrine / design-application sections from every chapter Markdown (full rglob, no hand-picked list)."""
import pathlib, re, sys
root = pathlib.Path(sys.argv[1])
want = ("## 上流指針", "### 本章での適用", "### 確定判断ごとの原則採否")
for p in sorted(root.rglob("*.md")):
    lines = p.read_text(encoding="utf-8").splitlines()
    print("=" * 10, p.name)
    for m in ("設計解釈の記録経路", "unrecorded", "legacy_backfill"):
        if any(m in l for l in lines):
            print("  marker:", m)
    on = False
    for l in lines:
        if l.startswith("#"):
            on = any(l.startswith(w) for w in want)
        if on:
            print(l[:700])

